//! `k2 zen guide libs` (prd-widget-size-and-shared-libs-v1 §7, vs-live L9):
//! K2's shared widget libraries, generated by `contract-gen` from
//! `src/shared/zen-lib.json` into a fenced block in `cli/k2`. The page works
//! with no daemon running, like every guide topic, and the freshness test in
//! `contract::gen` fails when the manifest and the block differ.
//!
//! Every request it shows is a line (`uplot@1`, `three@0.186`), never a
//! patch, so nothing it teaches breaks when K2 vendors the next patch.

use crate::zen::bundle::{human_bytes, MAX_BUNDLE_BYTES, MAX_CODE_BYTES, WARN_CODE_BYTES};
use crate::zen::stdlib::{line_of, LibSource, ZenLibEntry, ZenLibManifest};

/// The snapshot key of the block (a block inside `cli/k2`, like `study app-api`).
pub const LIBS_KEY: &str = "cli/k2#zen guide libs";
/// The block's begin marker in `cli/k2`.
pub const LIBS_BEGIN: &str = "# >>> generated by contract-gen: zen guide libs";
/// Every guide page but `api` is at most this many lines (FC33).
pub const LIBS_MAX_LINES: usize = 80;

/// What to pick for a job, in the guide's order: `(job, library id)`. A row
/// shows only while K2 ships that library.
pub const PICKS: &[(&str, &str)] = &[
    ("lines, sparklines", "uplot"),
    ("bar, pie, doughnut", "chart.js"),
    ("big dashboards", "echarts"),
    ("your own charts", "d3"),
    ("markdown (safe)", "k2-markdown"),
    ("tables", "k2-table"),
    ("code highlighting", "highlight.js"),
    ("maths", "katex"),
    ("3D", "three"),
    ("2D games", "kaplay"),
    ("UI components", "preact"),
    ("a help button", "k2-help"),
    ("a Thread panel", "k2-thread"),
];

/// The request a widget writes for a row: `<id>@<line>`.
pub fn line_request(e: &ZenLibEntry) -> String {
    format!("{}@{}", e.id, line_of(&e.version))
}

/// The guide page text (no shell wrapping).
pub fn guide_libs_page(m: &ZenLibManifest) -> String {
    let mut s = String::new();
    s.push_str("k2 zen guide libs — K2's shared libraries for custom widgets\n\n");
    s.push_str(&format!(
        "K2 ships these with the app. A widget names them in manifest.json and never\n\
copies them: K2 inlines each one as a nonced classic script after k2.js and\n\
before your own scripts, so your code calls its global (uPlot, Chart, ...).\n\
They don't count toward the code limit ({}; a warning above {}) or the\n\
page limit ({}); a widget may load up to {} of them. Every library\n\
runs inside the widget's sealed frame, with the widget's caps and no more.\n\n",
        human_bytes(MAX_CODE_BYTES),
        human_bytes(WARN_CODE_BYTES),
        human_bytes(MAX_BUNDLE_BYTES),
        human_bytes(m.max_bytes_per_widget as usize),
    ));
    s.push_str(
        "ASK FOR A LINE, NOT A PATCH\n\
  \"requires\": { \"libs\": [\"uplot@1\", \"chart.js@4\"] }\n\
  A line is the major (uplot@1), or 0.minor below 1.0 (three@0.186). K2\n\
  updates patches inside a line, so the widget keeps working.\n",
    );
    s.push_str(&format!(
        "  One file from a CDN: {{\"url\": \"https://cdn.jsdelivr.net/npm/x@1.2.3/x.min.js\",\n  \"integrity\": \"sha384-...\"}}, an exact version, from one of\n  {}.\n\
  The list is part of the version you sign, like your code.\n\n",
        m.cdn_hosts.join(", ")
    ));
    s.push_str("WHICH TO PICK\n");
    let picks: Vec<(&str, &ZenLibEntry)> =
        PICKS.iter().filter_map(|(job, id)| m.libs.iter().find(|e| e.id == *id).map(|e| (*job, e))).collect();
    let w_job = picks.iter().map(|(j, _)| j.len()).max().unwrap_or(0).max("dates, numbers".len());
    let w_req = picks.iter().map(|(_, e)| line_request(e).len()).max().unwrap_or(0);
    for (job, e) in &picks {
        s.push_str(&format!("  {job:<w_job$}  {:<w_req$}  {}\n", line_request(e), human_bytes(e.total_bytes() as usize)));
    }
    s.push_str(&format!(
        "  {:<w_job$}  no library: the browser's Intl.DateTimeFormat,\n  {:<w_job$}  Intl.RelativeTimeFormat and Intl.NumberFormat\n\n",
        "dates, numbers", ""
    ));
    s.push_str("EVERY LIBRARY: request, global, licence, size\n");
    let w_r = m.libs.iter().map(|e| line_request(e).len()).max().unwrap_or(0);
    let w_g = m.libs.iter().map(|e| e.global.len()).max().unwrap_or(0);
    let w_l = m.libs.iter().map(|e| e.license.len()).max().unwrap_or(0);
    for e in &m.libs {
        let size = human_bytes(e.total_bytes() as usize);
        let tag = match e.source {
            LibSource::Bundled => "",
            LibSource::Download => "  download",
        };
        let row = format!("  {:<w_r$}  {:<w_g$}  {:<w_l$}  {size:>7}{tag}", line_request(e), e.global, e.license);
        s.push_str(row.trim_end());
        s.push('\n');
    }
    s.push_str(
        "\n\"download\": fetched once by this computer's K2 on first use, checked, then\n\
kept (refused when the computer is air-gapped). Notes on each library are in\n\
the k2-zen skill. Check a widget with k2 zen validate --widget <name>: it\n\
prints the size line and says when a file looks like a copied library.\n",
    );
    s
}

/// The fenced block in `cli/k2` (markers included).
pub fn libs_block(m: &ZenLibManifest) -> String {
    let page = guide_libs_page(m);
    assert!(!page.contains("\nEOF\n"), "the libs page can't hold a heredoc terminator");
    format!(
        "{LIBS_BEGIN} (do not edit; {})\n_zen_guide_page_libs() {{\n    cat <<'EOF'\n{page}EOF\n}}\n{}\n",
        super::gen::REGEN,
        super::gen::CLI_END
    )
}

#[cfg(test)]
mod tests {
    use super::*;
    use crate::zen::stdlib::zen_lib_manifest;

    #[test]
    fn the_page_is_short_names_every_row_by_its_line_and_the_limits() {
        let m = zen_lib_manifest();
        let page = guide_libs_page(m);
        let n = page.lines().count();
        assert!(n <= LIBS_MAX_LINES, "guide libs is {n} lines (max {LIBS_MAX_LINES})");
        assert!(page.starts_with("k2 zen guide libs —"));
        for l in page.lines() {
            assert!(l.chars().count() <= 80, "a line over 80 columns: {l:?}");
        }
        for e in &m.libs {
            let req = line_request(e);
            assert!(page.lines().any(|l| l.starts_with(&format!("  {req} "))), "no row for {req}");
            assert!(!page.contains(&e.key()), "{} is taught as a patch, not a line", e.key());
        }
        for want in ["1 MB", "512 KB", "3.5 MB", "8 MB", "uplot@1", "Intl.DateTimeFormat"] {
            assert!(page.contains(want), "the page names {want}");
        }
    }

    #[test]
    fn every_request_the_page_shows_resolves() {
        let m = zen_lib_manifest();
        for e in &m.libs {
            let r = crate::zen::stdlib::LibRef::from_json(&serde_json::json!(line_request(e))).expect("parses");
            assert_eq!(crate::zen::stdlib::find(m, &r).map(|x| x.key()), Some(e.key()), "{}", line_request(e));
        }
    }

    #[test]
    fn lines_follow_the_rule() {
        assert_eq!(line_of("1.6.32"), "1");
        assert_eq!(line_of("3001.0.19"), "3001");
        assert_eq!(line_of("0.186.0"), "0.186");
        assert_eq!(line_of("0.20.0"), "0.20");
        assert_eq!(line_of("18.0.14"), "18");
    }
}
